import {api} from './accounts.mjs';
import {label,ui} from './language.mjs';
import {searchText,pageItems} from './lists.mjs';
import {pagination} from './directory-ui.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountAdministration(root,store,{onDelete,onRestore,onRecover,onErase,onViewArchive}){
 const [a,t]=await Promise.all([api('admin/accounts',{proof:store.proof}),api('admin/trash',{proof:store.proof})]);if(!root.isConnected)return;
 const typeLabels={mothers:'Maternal profile',children:'Child profile',growth:'Measurement',vaccines:'Vaccination',inventory:'Vaccine batch',guides:'Clinic guide',visits:'Visit'};let query='',accountPage=1,trashPage=1,requestedOnly=false;const selectedAccounts=new Set(),selectedTrash=new Set();const selection=(kind,set,items)=>ui`<div class="bulk-toolbar"><label><input type="checkbox" data-select-page="${kind}" ${items.length&&items.every(x=>set.has(x.id))?'checked':''}>Select this page</label><span>${label('{count} selected',{count:set.size})}</span><button class="row-button danger-action" data-erase-selected="${kind}" ${set.size?'':'disabled'}>Delete selected</button><button class="row-button" data-clear-selected="${kind}">Clear selection</button></div>`;root.innerHTML=ui`<nav class="bulk-toolbar" aria-label="Account administration sections"><button class="row-button" data-admin-section="admin-account-section">Clinic accounts</button><button class="row-button" data-admin-section="admin-trash-section">Trash</button><button class="row-button" data-admin-section="admin-health-section">Health archive</button></nav><p class="notice">Delete and restore require an internet connection and a synced clinic copy. Deleting accounts archives their health records and frees profile IDs. Health archives are read-only and remain with the clinic.</p><div class="toolbar"><label class="search-box" for="admin-search">Search accounts and Trash<input id="admin-search" type="search" placeholder="Search name or username…"></label></div><section class="panel admin-section" id="admin-account-section"><h2>Clinic accounts</h2><label for="recovery-only-filter"><input type="checkbox" id="recovery-only-filter">Show password help requests only</label><div id="admin-accounts"></div></section><section class="panel admin-section" id="admin-trash-section"><h2>Trash</h2><p>Restoring a profile does not automatically restore patient links or companion access. Refunded reservations return as cancelled and need staff approval again.</p><div id="admin-trash"></div></section><section class="panel admin-section" id="admin-health-section"><h2>Health archive</h2><p>Historical health records stay here after accounts or profiles are removed. Reused profile IDs do not share this history with new patients.</p><div id="health-archives"></div></section>`;
 function draw(){const accounts=pageItems(a.accounts.filter(x=>(!requestedOnly||x.recoveryRequestedAt)&&searchText(x.displayName+' '+x.username).includes(searchText(query))),accountPage);accountPage=accounts.page;root.querySelector('#admin-accounts').innerHTML=selection('account',selectedAccounts,accounts.items.filter(x=>!x.current))+accounts.items.map(x=>ui`<div class="admin-row"><label class="record-select"><input type="checkbox" data-select-account="${esc(x.id)}" ${selectedAccounts.has(x.id)?'checked':''} ${x.current?'disabled':''} aria-label="${esc(x.displayName+' · @'+x.username)}"></label><div><strong>${esc(x.displayName)}</strong>${x.recoveryRequestedAt?ui`<span class="badge overdue">Password help requested</span>`:''}<small>@${esc(x.username)} · ${label(x.role==='staff'?'Clinic staff':'Patient / guardian')} · ${label(x.active?'Active':'In Trash')}</small></div>${x.current?ui`<span class="badge">Current account</span>`:x.active?ui`<div class="row-actions"><button class="row-button" data-recover-account="${esc(x.id)}">Issue recovery code</button><button class="row-button danger-action" data-delete-account="${esc(x.id)}">Delete account</button></div>`:ui`<div class="row-actions"><span class="badge muted">In Trash</span><button class="row-button danger-action" data-delete-account="${esc(x.id)}">Archive & release IDs</button></div>`}</div>`).join('')+pagination(accounts,'admin-accounts');const entries=pageItems(t.entries.filter(x=>searchText(x.summary).includes(searchText(query))),trashPage);trashPage=entries.page;root.querySelector('#admin-trash').innerHTML=selection('trash',selectedTrash,entries.items)+entries.items.map(x=>ui`<div class="admin-row"><label class="record-select"><input type="checkbox" data-select-trash="${esc(x.id)}" ${selectedTrash.has(x.id)?'checked':''} aria-label="${esc(x.summary)}"></label><div><strong>${esc(x.summary)}</strong><small>${label(x.kind==='account'?'Account':typeLabels[x.record_type]??'Care record')} · ${new Date(x.deleted_at).toLocaleDateString()}</small></div><div class="row-actions"><button class="row-button" data-restore-trash="${esc(x.id)}">Restore</button><button class="row-button danger-action" data-purge-trash="${esc(x.id)}">Archive & release IDs</button></div></div>`).join('')+(entries.total?'':ui`<p>Trash is empty.</p>`)+pagination(entries,'admin-trash');}
 let archivePage=1,archiveRequest=0;async function drawArchives(){const serial=++archiveRequest;try{const view=await api('admin/archives?query='+encodeURIComponent(query)+'&page='+archivePage,{proof:store.proof});if(!root.isConnected||serial!==archiveRequest)return;archivePage=view.page;root.querySelector('#health-archives').innerHTML=view.items.map(item=>ui`<div class="admin-row"><div><strong>${esc(item.summary)}</strong><small>${label('Archived on {date}',{date:new Date(item.archivedAt).toLocaleString()})}</small></div><button class="row-button" data-view-archive="${esc(item.id)}">View archive</button></div>`).join('')+(view.total?'':ui`<p>No archived health records match this search.</p>`)+pagination(view,'health-archives');}catch(error){if(root.isConnected&&serial===archiveRequest)root.querySelector('#health-archives').textContent=error.message;}}
 root.querySelector('#admin-search').oninput=e=>{query=e.target.value;accountPage=trashPage=archivePage=1;draw();void drawArchives();};
 root.querySelector('#recovery-only-filter').onchange=e=>{requestedOnly=e.target.checked;accountPage=1;draw();};
 root.onchange=e=>{const box=e.target;if(box.matches('[data-select-account]')){box.checked?selectedAccounts.add(box.dataset.selectAccount):selectedAccounts.delete(box.dataset.selectAccount);}else if(box.matches('[data-select-trash]')){box.checked?selectedTrash.add(box.dataset.selectTrash):selectedTrash.delete(box.dataset.selectTrash);}else if(box.dataset.selectPage){const kind=box.dataset.selectPage,set=kind==='account'?selectedAccounts:selectedTrash;for(const item of root.querySelectorAll(kind==='account'?'[data-select-account]:not(:disabled)':'[data-select-trash]')){const id=kind==='account'?item.dataset.selectAccount:item.dataset.selectTrash;box.checked?set.add(id):set.delete(id);}}else return;draw();};
 root.onclick=e=>{const section=e.target.closest('[data-admin-section]');if(section){root.querySelector('#'+section.dataset.adminSection)?.scrollIntoView({block:'start'});return;}const archived=e.target.closest('[data-view-archive]');if(archived){onViewArchive(archived.dataset.viewArchive);return;}const bulk=e.target.closest('[data-erase-selected]');if(bulk){const kind=bulk.dataset.eraseSelected,set=kind==='account'?selectedAccounts:selectedTrash;onErase([...set].map(id=>({kind,id})));return;}const clear=e.target.closest('[data-clear-selected]');if(clear){(clear.dataset.clearSelected==='account'?selectedAccounts:selectedTrash).clear();draw();return;}const purge=e.target.closest('[data-purge-trash]');if(purge){onErase([{kind:'trash',id:purge.dataset.purgeTrash}]);return;}const recovery=e.target.closest('[data-recover-account]');if(recovery){onRecover(a.accounts.find(x=>x.id===recovery.dataset.recoverAccount));return;}const deletion=e.target.closest('[data-delete-account]');if(deletion){onDelete(a.accounts.find(x=>x.id===deletion.dataset.deleteAccount));return;}const restore=e.target.closest('[data-restore-trash]');if(restore){onRestore(t.entries.find(x=>x.id===restore.dataset.restoreTrash));return;}const page=e.target.closest('[data-list-page]');if(page){if(page.dataset.listKey==='health-archives'){archivePage=Number(page.dataset.listPage);void drawArchives();return;}if(page.dataset.listKey==='admin-accounts')accountPage=Number(page.dataset.listPage);else trashPage=Number(page.dataset.listPage);draw();}};draw();void drawArchives();
}
